CREATE OR REPLACE FUNCTION public.fn_accounting_correction_prepare(p_ledger_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO,YMD'
    AS $$
DECLARE l public.chip_ledger%ROWTYPE;c public.clubs%ROWTYPE;u public.unions%ROWTYPE;
 scope uuid;endpoint_clubs uuid[];candidate_unions uuid[];party_kind text;party_id uuid;person uuid;party_name text;side int;
 intended public.accounting_correction_documents%ROWTYPE;surviving public.accounting_correction_documents%ROWTYPE;
 issuer_kind text;issuer_id uuid;sender uuid;issuer_name text;payee_kind text;payee_id uuid;recipient uuid;payee_name text;
 endpoint_type text;endpoint_id uuid;incident uuid;failure bigint;expected_key text;audience uuid[];issuer_users uuid[];payee_users uuid[];issued timestamptz:=clock_timestamp();
BEGIN
 SELECT * INTO STRICT l FROM public.chip_ledger WHERE id=p_ledger_id;
 IF l.category IS DISTINCT FROM 'correction' OR l.status IS DISTINCT FROM 'posted'
  OR l.amount IS NULL OR l.amount::text IN('NaN','Infinity','-Infinity') OR l.amount<=0 OR l.amount>9999999999.99 OR l.amount<>round(l.amount,2)
  OR l.created_at IS NULL OR NOT isfinite(l.created_at) OR l.created_at>issued
  OR l.from_type NOT IN('union_bank','union_wallet','club_treasury','agent_wallet','player_wallet')
  OR l.to_type NOT IN('union_bank','union_wallet','club_treasury','agent_wallet','player_wallet')
  OR l.from_entity_id IS NULL OR l.to_entity_id IS NULL
  OR l.table_id IS NOT NULL OR l.hand_id IS NOT NULL OR l.tournament_id IS NOT NULL OR l.settlement_id IS NOT NULL
 THEN RAISE EXCEPTION 'correction_document_source_unverified' USING ERRCODE='23514';END IF;
 -- These are authoritative stored linkage facts, not authentication of the
 -- posted_via marker or proof of the original caller's unrecorded input bytes.
 incident:=NULLIF(l.metadata->>'incident_id','')::uuid;
 failure:=NULLIF(l.metadata->>'write_failure_id','')::bigint;
 expected_key:='correction:'||COALESCE('lwf:'||failure::text,'inc:'||incident::text);
 IF (incident IS NULL AND failure IS NULL) OR l.idempotency_key IS DISTINCT FROM expected_key
  OR (incident IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ca_drift_incidents WHERE id=incident))
  OR (failure IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ca_ledger_write_failures WHERE id=failure))
 THEN RAISE EXCEPTION 'correction_document_linkage_unverified' USING ERRCODE='23514';END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO endpoint_clubs FROM unnest(ARRAY[
  CASE WHEN l.from_type='club_treasury' THEN l.from_entity_id END,
  CASE WHEN l.to_type='club_treasury' THEN l.to_entity_id END])x WHERE x IS NOT NULL;
 scope:=l.club_id;
 IF scope IS NULL AND cardinality(endpoint_clubs)=1 THEN scope:=endpoint_clubs[1];END IF;
 IF scope IS NULL OR COALESCE(cardinality(endpoint_clubs),0)>1
  OR EXISTS(SELECT 1 FROM unnest(endpoint_clubs)x WHERE x<>scope)
 THEN RAISE EXCEPTION 'correction_document_club_scope_unverified' USING ERRCODE='23514';END IF;
 SELECT * INTO c FROM public.clubs WHERE id=scope FOR SHARE;
 IF NOT FOUND OR c.owner_id IS NULL THEN RAISE EXCEPTION 'correction_document_club_scope_unverified' USING ERRCODE='23514';END IF;
 IF l.union_id IS NOT NULL THEN
  SELECT * INTO u FROM public.unions WHERE id=l.union_id FOR SHARE;
  IF NOT FOUND OR u.owner_id IS NULL THEN RAISE EXCEPTION 'correction_document_union_scope_unverified' USING ERRCODE='23514';END IF;
 END IF;
 FOR side IN 1..2 LOOP
  endpoint_type:=CASE side WHEN 1 THEN l.from_type ELSE l.to_type END;
  endpoint_id:=CASE side WHEN 1 THEN l.from_entity_id ELSE l.to_entity_id END;
  IF endpoint_type IN('union_bank','union_wallet') THEN
   SELECT array_agg(DISTINCT id ORDER BY id) INTO candidate_unions FROM (
    SELECT x.id FROM public.unions x WHERE x.id=endpoint_id
    UNION SELECT w.union_id FROM public.union_wallets w WHERE w.id=endpoint_id)matches;
   IF l.union_id IS NULL OR cardinality(candidate_unions) IS DISTINCT FROM 1 OR candidate_unions[1] IS DISTINCT FROM l.union_id
   THEN RAISE EXCEPTION 'correction_document_union_identity_unverified' USING ERRCODE='23514';END IF;
   party_kind:='union';party_id:=l.union_id;person:=u.owner_id;party_name:=COALESCE(NULLIF(btrim(u.name),''),'Union');
  ELSIF endpoint_type='club_treasury' THEN
   party_kind:='club';party_id:=scope;person:=c.owner_id;party_name:=COALESCE(NULLIF(btrim(c.name),''),'Club');
  ELSE
   party_kind:=CASE endpoint_type WHEN 'agent_wallet' THEN 'agent' ELSE 'player' END;
   party_id:=endpoint_id;person:=endpoint_id;
   SELECT COALESCE(NULLIF(btrim(p.username),''),'Member') INTO party_name FROM public.profiles p WHERE p.id=person;
  END IF;
  IF person IS NULL OR party_name IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=person)
  THEN RAISE EXCEPTION 'correction_document_recipient_unverified' USING ERRCODE='23514';END IF;
  IF side=1 THEN issuer_kind:=party_kind;issuer_id:=party_id;sender:=person;issuer_name:=party_name;
  ELSE payee_kind:=party_kind;payee_id:=party_id;recipient:=person;payee_name:=party_name;END IF;
 END LOOP;
 -- A club must not receive each individual's correction as a back door into
 -- weekly rakeback detail. The sender remains a real conversation participant.
 SELECT array_agg(user_id ORDER BY user_id) INTO issuer_users FROM public.fn_accounting_party_users(issuer_kind,issuer_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO payee_users FROM public.fn_accounting_party_users(payee_kind,payee_id);
 IF COALESCE(cardinality(issuer_users),0)=0 OR COALESCE(cardinality(payee_users),0)=0
  OR sender=ANY(issuer_users) IS NOT TRUE OR recipient=ANY(payee_users) IS NOT TRUE
 THEN RAISE EXCEPTION 'correction_document_recipient_unverified' USING ERRCODE='23514';END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO audience FROM unnest(
  CASE WHEN issuer_kind='club' AND payee_kind IN('agent','player') THEN payee_users ELSE issuer_users||payee_users END)x;
 intended:=ROW(gen_random_uuid(),1,l.id,gen_random_uuid(),scope,l.union_id,l.club_id,l.union_id,to_jsonb(l),l.amount,
  issuer_kind,issuer_id,payee_kind,payee_id,sender,issuer_name,payee_name,audience,incident,failure,l.created_at,issued)::public.accounting_correction_documents;
 INSERT INTO public.accounting_correction_documents SELECT intended.*;
 SELECT * INTO surviving FROM public.accounting_correction_documents WHERE id=intended.id;
 IF NOT FOUND OR to_jsonb(surviving) IS DISTINCT FROM to_jsonb(intended)
 THEN RAISE EXCEPTION 'correction_document_provenance_write_missing' USING ERRCODE='23514';END IF;
END $$;

CREATE OR REPLACE FUNCTION public.fn_accounting_credit_change_body_v1(p_document_id uuid, p_invoice_number text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE d public.accounting_credit_change_documents_v1%ROWTYPE;
 o public.accounting_credit_reduction_operations_v1%ROWTYPE;
BEGIN
 SELECT * INTO STRICT d FROM public.accounting_credit_change_documents_v1 WHERE id=p_document_id;
 SELECT * INTO STRICT o FROM public.accounting_credit_reduction_operations_v1 WHERE id=d.operation_receipt_id;
 RETURN 'Credit Line Updated '||p_invoice_number||E'\nIssued By: '||d.issuer_name||E'\nFor: '||d.recipient_name
  ||E'\nRequested Reduction: '||to_char(o.requested_reduction,'FM999,999,999,999,990.00')
  ||E'\nApplied Reduction: '||to_char(o.applied_reduction,'FM999,999,999,999,990.00')
  ||E'\nLimit After This Change: '||to_char(o.after_limit,'FM999,999,999,999,990.00')
  ||E'\nFunding After This Change: '||CASE WHEN o.after_prepaid THEN 'Prepaid' ELSE 'Credit' END
  ||E'\nThis records a credit-capacity change. No chips were transferred and no payment is due.';
END $$;

CREATE OR REPLACE FUNCTION public.fn_accounting_credit_change_contract_v1(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO,YMD'
    AS $$
DECLARE d public.accounting_credit_change_documents_v1%ROWTYPE;
 o public.accounting_credit_reduction_operations_v1%ROWTYPE;
 i public.settlement_invoices%ROWTYPE;payload jsonb;audience uuid[];
BEGIN
 SELECT * INTO d FROM public.accounting_credit_change_documents_v1 WHERE invoice_id=p_invoice_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'credit_change_document_missing' USING ERRCODE='23514';END IF;
 SELECT * INTO o FROM public.accounting_credit_reduction_operations_v1 WHERE id=d.operation_receipt_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'credit_change_operation_missing' USING ERRCODE='23514';END IF;
 SELECT array_agg(DISTINCT u ORDER BY u) INTO audience FROM unnest(ARRAY[o.actor_user_id,o.target_user_id])u;
 payload:=public.fn_accounting_credit_change_payload_v1(d.id);
 SELECT * INTO i FROM public.settlement_invoices WHERE id=d.invoice_id;
 IF NOT FOUND OR d.audience_user_ids IS DISTINCT FROM audience OR d.issued_at IS DISTINCT FROM o.recorded_at
  OR i.invoice_type IS DISTINCT FROM 'credit_limit_change' OR i.club_id IS DISTINCT FROM o.club_id
  OR i.from_entity_type IS DISTINCT FROM 'club' OR i.from_entity_id IS DISTINCT FROM o.club_id::text
  OR i.to_entity_type IS DISTINCT FROM 'agent' OR i.to_entity_id IS DISTINCT FROM o.target_user_id::text
  OR i.gross_amount IS DISTINCT FROM o.applied_reduction OR i.net_amount IS DISTINCT FROM o.applied_reduction
  OR i.deductions IS DISTINCT FROM 0 OR i.status IS DISTINCT FROM 'generated'
  OR i.chips_transferred IS DISTINCT FROM false OR i.transferred_at IS NOT NULL OR i.due_at IS NOT NULL
  OR i.chip_transfer_id IS NOT NULL OR i.adjusts_invoice_id IS NOT NULL OR i.period_id IS NOT NULL
  OR i.source_ledger_id IS NOT NULL OR i.source_credit_invoice_id IS NOT NULL OR i.source_credit_payment_id IS NOT NULL
  OR i.source_credit_reduction_operation_id IS DISTINCT FROM o.id
  OR i.overdue_at IS NOT NULL OR i.reminders_sent IS DISTINCT FROM 0 OR i.last_reminder_at IS NOT NULL
  OR i.notes IS NOT NULL OR i.created_at IS DISTINCT FROM d.issued_at
  OR i.invoice_number IS NULL OR i.breakdown IS DISTINCT FROM jsonb_build_object('category','credit_limit_change','credit_change',payload)
 THEN RAISE EXCEPTION 'credit_change_document_contract_mismatch' USING ERRCODE='23514';END IF;
 RETURN payload;
END $$;

CREATE OR REPLACE FUNCTION public.fn_accounting_invoice_deliver_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 PERFORM public.fn_deliver_accounting_invoice(NEW.id);
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.fn_accounting_next_invoice_number() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE y int:=extract(year FROM now() AT TIME ZONE 'America/Chicago'); n bigint;
BEGIN
 INSERT INTO public.accounting_invoice_counters(year,next_number) VALUES(y,2)
 ON CONFLICT(year) DO UPDATE SET next_number=accounting_invoice_counters.next_number+1
 RETURNING next_number-1 INTO n;
 RETURN 'CA-'||y::text||'-'||lpad(n::text,8,'0');
END $$;

CREATE OR REPLACE FUNCTION public.fn_accounting_transfer_document_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NEW.category='correction' THEN PERFORM public.fn_accounting_correction_prepare(NEW.id);END IF;
 PERFORM public.fn_invoice_accounting_ledger_transfer(NEW.id);
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.fn_ca_autoledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  spec text; col text; acct text;
  o jsonb; nn jsonb;
  d numeric; oldv numeric; newv numeric;
  cat text; cp text; cpid uuid;
  v_club uuid; v_union uuid; v_entity uuid;
  actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN NEW;
  END IF;

  o  := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
  nn := to_jsonb(NEW);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');
  cp  := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN cpid := NULL;
  END;
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (nn->>'id')::uuid
    WHEN nn ? 'club_id' THEN NULLIF(nn->>'club_id','')::uuid
    ELSE NULL END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (nn->>'id')::uuid
    WHEN nn ? 'union_id' THEN NULLIF(nn->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME = 'agents' THEN NULLIF(nn->>'user_id','')::uuid
    WHEN TG_TABLE_NAME = 'club_members' THEN NULLIF(nn->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(nn->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := COALESCE(NULLIF(o->>col,'')::numeric, 0);
    newv := COALESCE(NULLIF(nn->>col,'')::numeric, 0);
    d := round(newv - oldv, 2);
    CONTINUE WHEN d = 0;

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance, pre_to_balance, post_to_balance)
      VALUES (actor,
        CASE WHEN d > 0 THEN cp   ELSE acct END,
        CASE WHEN d > 0 THEN cpid ELSE v_entity END,
        CASE WHEN d > 0 THEN NULL ELSE TG_TABLE_NAME || '.' || col END,
        CASE WHEN d > 0 THEN acct ELSE cp END,
        CASE WHEN d > 0 THEN v_entity ELSE cpid END,
        CASE WHEN d > 0 THEN TG_TABLE_NAME || '.' || col ELSE NULL END,
        abs(d), cat, v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' delta ' || d::text,
        CASE WHEN d < 0 THEN oldv END, CASE WHEN d < 0 THEN newv END,
        CASE WHEN d > 0 THEN oldv END, CASE WHEN d > 0 THEN newv END);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.fn_ca_finding_key(p_dedupe_key text, p_classification text, p_layer text, p_club_id uuid, p_union_id uuid) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  k text := COALESCE(p_dedupe_key, '');
  before text;
BEGIN
  FOR i IN 1..4 LOOP
    before := k;
    k := regexp_replace(k, ':[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$', '');
    k := regexp_replace(k, ':[0-9a-fA-F]{32}$', '');
    k := regexp_replace(k, ':[0-9]{4}-[0-9]{2}-[0-9]{2}(-[0-9]{2})?$', '');
    EXIT WHEN k = before;
  END LOOP;

  IF k = '' THEN
    k := COALESCE(p_classification, 'unknown');
  END IF;

  RETURN k
      || '|' || COALESCE(p_layer, 'unknown')
      || '|' || COALESCE(p_club_id::text, '-')
      || '|' || COALESCE(p_union_id::text, '-');
END $_$;

CREATE OR REPLACE FUNCTION public.fn_ca_incident_notify(p_incident_id uuid, p_kind text, p_headline text, p_senior_only boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inc  public.ca_drift_incidents;
  rec  uuid;
  n    int := 0;
  club_name  text;
  union_name text;
  body text;
  age_min int;
  v_finding text;
  v_state   text;
  v_kind    text;
  v_fresh   boolean;
  v_withheld text := NULL;
  v_findings numeric;
  /* A LIVENESS FINDING CARRIES NO CHIP AMOUNT AND STILL MATTERS (2026-09-12).
     These detectors answer "is the platform dealing", not "do the chips add
     up", so their discrepancy is always 0.00 and the money gate below would
     mute every one of them. On 2026-09-12 the engine dealt zero tournament
     hands for five hours and every detector that could have said so would have
     been filed and muted here. Measured before changing it: 1,041 pushes were
     withheld on that gate in seven days and exactly 10 were liveness findings,
     so relaxing it generally would have sent a thousand pages a week. Named
     explicitly so a future detector has to ask to be on this list, and so the
     rule that decides who gets woken is readable in one glance. */
  v_liveness CONSTANT text[] := ARRAY[
    'fn_ca_conservation_sweep:fn_ca_orphaned_running_tournaments',
    'fn_ca_conservation_sweep:fn_ca_tables_that_cannot_deal',
    'fn_ca_conservation_sweep:fn_ca_knockout_door_stalled',
    'fn_ca_conservation_sweep:fn_ca_stranded_completing_tournaments',
    'fn_ca_conservation_sweep:fn_ca_rake_rollup_writer_silent',
    'fn_ca_conservation_sweep:fn_ca_absent_tournament_players'
  ];
  v_is_liveness boolean;
BEGIN
  SELECT * INTO inc FROM public.ca_drift_incidents WHERE id = p_incident_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_kind := CASE
              WHEN p_kind = 'escalated'    THEN 'escalated'
              WHEN inc.status = 'resolved' THEN 'resolved'
              ELSE 'raised'
            END;

  v_is_liveness := COALESCE(inc.source, '') = ANY (v_liveness);
  v_findings := COALESCE(
      NULLIF(inc.metadata->>'row_count','')::numeric,
      jsonb_array_length(COALESCE(inc.metadata->'rows','[]'::jsonb))::numeric,
      0);

  /* DAN'S RULE, 2026-09-06. Three gates, on the PUSH only. The incident is
     still filed, the event row is still written, the board still shows
     everything - what changes is whose night it interrupts.

     Order matters: 'resolved' is checked first because a fix is the case he
     named explicitly, and it would otherwise slip through on a critical. */
  IF v_kind = 'resolved' THEN
    v_withheld := 'a fix is not a page';
  ELSIF lower(COALESCE(inc.severity,'')) <> 'critical' THEN
    v_withheld := 'severity ' || COALESCE(inc.severity,'null') || ' is not critical';
  ELSIF COALESCE(inc.discrepancy_amount, 0) = 0 AND NOT v_is_liveness THEN
    v_withheld := 'nothing is unaccounted for (0.00)';
  ELSIF COALESCE(inc.discrepancy_amount, 0) = 0 AND v_is_liveness AND v_findings = 0 THEN
    /* A liveness detector that found nothing is the healthy case and is not a
       page either. Only a detector that actually found something gets through. */
    v_withheld := 'the check is live and found nothing';
  END IF;

  IF v_withheld IS NOT NULL THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (inc.id, 'notify_withheld',
            jsonb_build_object('reason', v_withheld, 'kind', v_kind,
                               'severity', inc.severity,
                               'discrepancy', inc.discrepancy_amount,
                               'headline', left(p_headline, 110),
                               'rule', 'Dan 2026-09-06: only critical errors that need my attention'));
    RETURN 0;
  END IF;

  SELECT name INTO club_name  FROM public.clubs  WHERE id = inc.club_id;
  SELECT name INTO union_name FROM public.unions WHERE id = inc.union_id;
  age_min := GREATEST(0, floor(extract(epoch FROM now() - inc.detected_at) / 60))::int;

  IF v_is_liveness AND COALESCE(inc.discrepancy_amount, 0) = 0 THEN
    /* Say what was actually found. "drift 0.00 chips" reads as a rounding
       error, and an alert that reads like a rounding error gets ignored. */
    body := format(
      '%s | %s: %s finding(s) on the %s layer. %s%sAge %smin, reconcile target %s.',
      upper(inc.severity), inc.entity_type,
      to_char(v_findings, 'FM999999999990'),
      inc.layer,
      COALESCE('Club ' || club_name || '. ', ''),
      COALESCE('Union ' || union_name || '. ', ''),
      age_min, to_char(inc.deadline_at, 'HH24:MI UTC'));
  ELSE
    body := format(
      '%s | %s drift %s chips (%s layer). Expected %s, actual %s. %s%sAge %smin, reconcile target %s. Auto-repair: %s.',
      upper(inc.severity), inc.classification,
      to_char(COALESCE(inc.discrepancy_amount,0), 'FM999999999990.00'),
      inc.layer,
      COALESCE(to_char(inc.expected_amount,'FM999999999990.00'),'?'),
      COALESCE(to_char(inc.actual_amount,'FM999999999990.00'),'?'),
      COALESCE('Club ' || club_name || '. ', ''),
      COALESCE('Union ' || union_name || '. ', ''),
      age_min, to_char(inc.deadline_at, 'HH24:MI UTC'), inc.auto_repair_status);
  END IF;

  v_finding := public.fn_ca_finding_key(inc.dedupe_key, inc.classification, inc.layer,
                                        inc.club_id, inc.union_id);
  v_state := md5(
      v_kind
      || '|' || COALESCE(inc.severity,'?')
      || '|' || COALESCE(inc.classification,'?')
      || '|' || COALESCE(inc.layer,'?')
      || '|' || COALESCE(inc.club_id::text,'-')
      || '|' || COALESCE(inc.union_id::text,'-')
      || '|' || CASE WHEN v_kind = 'escalated'
                     THEN COALESCE(inc.escalation_level, 0)::text ELSE '' END);

  FOR rec IN SELECT unnest(public.fn_ca_incident_recipient_ids(inc, p_senior_only))
  LOOP
    BEGIN
      v_fresh := NULL;
      INSERT INTO public.ca_incident_notify_ledger AS l
        (recipient_id, finding_key, state_hash, last_kind, last_incident_id)
      VALUES (rec, v_finding, v_state, v_kind, inc.id)
      ON CONFLICT (recipient_id, finding_key) DO UPDATE
        SET state_hash = EXCLUDED.state_hash, last_kind = EXCLUDED.last_kind,
            last_incident_id = EXCLUDED.last_incident_id, last_sent_at = now(),
            send_count = l.send_count + 1
        WHERE l.state_hash IS DISTINCT FROM EXCLUDED.state_hash
      RETURNING true INTO v_fresh;

      IF NOT COALESCE(v_fresh, false) THEN
        INSERT INTO public.ca_incident_events (incident_id, kind, detail)
        VALUES (inc.id, 'notified',
                jsonb_build_object('already_reported', true, 'finding_key', v_finding,
                                   'state', v_kind, 'recipient', rec));
        CONTINUE;
      END IF;

      PERFORM public.fn_raise_notification(
        rec, 'financial_incident', left(p_headline, 110), left(body, 480),
        '/hub/club-arena/financial-incidents?id=' || inc.id::text,
        jsonb_build_object('incident_id', inc.id, 'finding_key', v_finding,
                           'classification', inc.classification, 'severity', inc.severity,
                           'discrepancy', inc.discrepancy_amount, 'club_id', inc.club_id,
                           'union_id', inc.union_id, 'deadline_at', inc.deadline_at));
      n := n + 1;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'notify_failed',
              jsonb_build_object('recipient', rec, 'error', SQLERRM));
    END;
  END LOOP;

  INSERT INTO public.ca_incident_events (incident_id, kind, detail)
  VALUES (inc.id, p_kind,
          jsonb_build_object('headline', p_headline, 'recipients', n,
                             'senior_only', p_senior_only, 'age_min', age_min,
                             'finding_key', v_finding, 'state', v_kind));
  RETURN n;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_incident_notify failed for %: %', p_incident_id, SQLERRM;
  RETURN 0;
END $$;

CREATE OR REPLACE FUNCTION public.fn_ca_raise_drift_incident(p_source text, p_classification text, p_severity text, p_dedupe_key text, p_discrepancy numeric DEFAULT NULL::numeric, p_expected numeric DEFAULT NULL::numeric, p_actual numeric DEFAULT NULL::numeric, p_layer text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_settlement_id text DEFAULT NULL::text, p_wallet_ids uuid[] DEFAULT NULL::uuid[], p_transaction_ids uuid[] DEFAULT NULL::uuid[], p_suspected_cause text DEFAULT NULL::text, p_ledger_balanced boolean DEFAULT NULL::boolean, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_class text := p_classification;
  v_sev   text := lower(COALESCE(p_severity,'critical'));
  v_stable text;
BEGIN
  IF NOT public.fn_ca_is_midway_scope(
    p_union_id, p_club_id, p_table_id, p_tournament_id, p_metadata
  ) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_detector_registry r WHERE r.source = p_source AND r.status = 'retired') THEN
    RETURN NULL;
  END IF;
  INSERT INTO public.ca_detector_registry (source, owner, sla_hours, note)
  VALUES (p_source, 'unassigned', 24, 'auto-registered on first sight (Phase 6 gate); give it an owner')
  ON CONFLICT (source) DO NOTHING;

  IF v_class IS NULL OR v_class NOT IN (
      'ledger_imbalance','settlement_error','duplicate_payment','missing_payment',
      'projection_delay','cache_mismatch','reporting_mismatch','delayed_event',
      'duplicate_event','rounding_error','incorrect_rake','incorrect_weighted_rake',
      'incorrect_rakeback','bbj_error','treasury_error','credit_line_error',
      'cross_club_posting','cross_union_posting','unauthorized_adjustment',
      'historical_migration','unknown') THEN
    v_class := 'unknown';
  END IF;
  IF v_sev NOT IN ('critical','warning','info') THEN v_sev := 'critical'; END IF;

  UPDATE public.ca_drift_incidents
     SET occurrences  = occurrences + 1,
         last_seen_at = now(),
         discrepancy_amount = COALESCE(p_discrepancy, discrepancy_amount),
         actual_amount      = COALESCE(p_actual, actual_amount),
         expected_amount    = COALESCE(p_expected, expected_amount),
         suspected_cause    = COALESCE(p_suspected_cause, suspected_cause),
         metadata           = COALESCE(p_metadata, metadata)
   WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'
   RETURNING id INTO v_id;

  IF v_id IS NOT NULL THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (v_id, 'recurred', jsonb_build_object('source', p_source,
            'discrepancy', p_discrepancy));
    RETURN v_id;
  END IF;

  /* ONE STANDING CONDITION IS ONE INCIDENT (2026-09-06).
     A sweep that puts the date in its key defeats the exact-match fold above
     and files a fresh critical every run: sweep:fn_bbj_promo_bank_check:
     2026-09-02 .. -09-06, five rows, all 6705.21, one condition.

     The amount is what makes this safe. `diamond-unexplained:2026-09-02-18`
     is an hourly bucket where each bucket is a DIFFERENT event, so folding on
     the key alone would hide real ones. A standing condition re-reports the
     same number; a new event reports a new one. Same detector, same key
     without its period label, same discrepancy - then and only then is it the
     same finding said twice. */
  v_stable := public.fn_ca_stable_dedupe_key(p_dedupe_key);
  IF v_stable <> p_dedupe_key THEN
    UPDATE public.ca_drift_incidents
       SET occurrences     = occurrences + 1,
           last_seen_at    = now(),
           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),
           metadata        = COALESCE(p_metadata, metadata)
     WHERE status <> 'resolved'
       AND source = p_source
       AND public.fn_ca_stable_dedupe_key(dedupe_key) = v_stable
       AND COALESCE(discrepancy_amount,0) = COALESCE(p_discrepancy,0)
     RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (v_id, 'recurred', jsonb_build_object(
        'source', p_source, 'rotated_key', p_dedupe_key,
        'note', 'same condition under a new period label; folded rather than re-filed'));
      RETURN v_id;
    END IF;
  END IF;

  /* DETECTOR STORM CAP (2026-09-09). One source cannot own the board.
     Reached only after the exact-key fold and the stable-key fold above have
     both declined to absorb this finding, i.e. it really would be a NEW row. */
  IF (SELECT count(*) FROM public.ca_drift_incidents
       WHERE source = p_source AND status <> 'resolved') >= 25 THEN
    UPDATE public.ca_drift_incidents
       SET occurrences = occurrences + 1, last_seen_at = now()
     WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'
     RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      INSERT INTO public.ca_drift_incidents (
        classification, severity, layer, source, dedupe_key,
        discrepancy_amount, suspected_cause, metadata)
      VALUES ('unknown', v_sev, COALESCE(p_layer,'unknown'), p_source,
        'storm:' || p_source, 0,
        'DETECTOR STORM: this source has 25 or more open incidents, so further findings are counted here rather than filed as new rows. See this incident''s event log for the original capped finding keys and reported discrepancies; this branch does not create a separate financial_alerts row for each finding. Fix the detector, or the condition behind it, then resolve this.',
        jsonb_build_object('storm', true, 'capped_from', p_dedupe_key))
      ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING
      RETURNING id INTO v_id;
      IF v_id IS NULL THEN
        UPDATE public.ca_drift_incidents
           SET occurrences = occurrences + 1, last_seen_at = now()
         WHERE dedupe_key = 'storm:' || p_source AND status <> 'resolved'
         RETURNING id INTO v_id;
      END IF;
    END IF;
    IF v_id IS NOT NULL THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (v_id, 'recurred', jsonb_build_object(
        'source', p_source, 'capped_dedupe_key', p_dedupe_key,
        'discrepancy', p_discrepancy, 'suspected_cause', p_suspected_cause,
        'note', 'counted on the storm incident: this source is over its open-incident cap'));
    END IF;
    RETURN v_id;
  END IF;

  INSERT INTO public.ca_drift_incidents (
    classification, severity, layer, source, dedupe_key,
    union_id, club_id, entity_type, entity_id, table_id, tournament_id,
    hand_id, settlement_id, wallet_ids, transaction_ids,
    expected_amount, actual_amount, discrepancy_amount,
    ledger_balanced, suspected_cause, metadata)
  VALUES (
    v_class, v_sev, COALESCE(p_layer,'unknown'), p_source, p_dedupe_key,
    p_union_id, p_club_id, p_entity_type, p_entity_id, p_table_id, p_tournament_id,
    p_hand_id, p_settlement_id, p_wallet_ids, p_transaction_ids,
    p_expected, p_actual, COALESCE(p_discrepancy, 0),
    p_ledger_balanced, p_suspected_cause, COALESCE(p_metadata,'{}'::jsonb))
  ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    UPDATE public.ca_drift_incidents
       SET occurrences     = occurrences + 1,
           last_seen_at    = now(),
           suspected_cause = COALESCE(p_suspected_cause, suspected_cause),
           metadata        = COALESCE(p_metadata, metadata)
     WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'
     RETURNING id INTO v_id;
    RETURN v_id;
  END IF;

  INSERT INTO public.ca_incident_events (incident_id, kind, detail)
  VALUES (v_id, 'created', jsonb_build_object('source', p_source));

  BEGIN
    PERFORM public.fn_raise_server_financial_alert(
      v_sev, 'drift_incident:' || p_source,
      v_class || ' drift ' || COALESCE(p_discrepancy,0)::text || ' chips',
      jsonb_build_object('incident_id', v_id) || COALESCE(p_metadata,'{}'::jsonb));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  IF p_severity = 'info' THEN
    NULL;
  ELSIF (SELECT count(*) FROM public.ca_drift_incidents
       WHERE created_at > now() - interval '2 minutes') >= 10 THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (v_id, 'notified', jsonb_build_object('storm_suppressed', true));
  ELSE
    PERFORM public.fn_ca_incident_notify(
      v_id, 'notified',
      to_char(COALESCE(p_discrepancy,0),'FM999999999990.00') || ' chip drift: ' || v_class,
      false);
  END IF;

  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  DECLARE v_state text; v_msg text;
  BEGIN
    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
    RAISE WARNING 'fn_ca_raise_drift_incident(%) failed: %', p_source, v_msg;
    BEGIN
      INSERT INTO public.ca_incident_file_failures
        (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)
      VALUES (p_source, p_dedupe_key, v_class, v_sev, p_discrepancy, v_state, v_msg);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN NULL;
  END;
END $$;

CREATE OR REPLACE FUNCTION public.fn_deliver_accounting_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_variable
DECLARE inv public.settlement_invoices%ROWTYPE; sender uuid; issuer_name text; recipient_name text;
 issuer_kind text; issuer_id uuid; recipient_id uuid; scope_id uuid; page_id uuid; users uuid[]; issuer_users uuid[]; recipient_users uuid[];
 person uuid; conv uuid; msg uuid; note uuid; body text; meta jsonb; count_sent int:=0; n int; line record; cashier public.accounting_cashier_events%ROWTYPE; cashier_payload jsonb; correction public.accounting_correction_documents%ROWTYPE; correction_payload jsonb; credit_change public.accounting_credit_change_documents_v1%ROWTYPE; credit_operation public.accounting_credit_reduction_operations_v1%ROWTYPE; credit_payload jsonb;
BEGIN
 SELECT * INTO inv FROM public.settlement_invoices WHERE id=p_invoice_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_missing' USING ERRCODE='23514'; END IF;
 IF public.fn_accounting_correction_is_unverified(inv.id)
 THEN RAISE EXCEPTION 'historical_correction_document_unverified' USING ERRCODE='23514';END IF;
 IF inv.net_amount IS NULL OR inv.net_amount::text IN('NaN','Infinity','-Infinity') OR inv.net_amount<>round(inv.net_amount,2)
 THEN RAISE EXCEPTION 'invalid_invoice_amount' USING ERRCODE='23514'; END IF;
 issuer_kind:=inv.from_entity_type; issuer_id:=inv.from_entity_id::uuid; recipient_id:=inv.to_entity_id::uuid;
 scope_id:=COALESCE(inv.club_id,issuer_id);
 IF inv.invoice_type='credit_limit_change' THEN
  credit_payload:=public.fn_accounting_credit_change_contract_v1(inv.id);
  SELECT * INTO STRICT credit_change FROM public.accounting_credit_change_documents_v1 WHERE invoice_id=inv.id;
  SELECT * INTO STRICT credit_operation FROM public.accounting_credit_reduction_operations_v1 WHERE id=credit_change.operation_receipt_id;
  users:=credit_change.audience_user_ids;sender:=credit_operation.actor_user_id;
  issuer_kind:='club';issuer_id:=credit_operation.club_id;scope_id:=credit_operation.club_id;
  issuer_name:=credit_change.issuer_name;recipient_name:=credit_change.recipient_name;
 ELSIF inv.invoice_type='accounting_correction' THEN
  SELECT * INTO correction FROM public.accounting_correction_documents WHERE invoice_id=inv.id;
  IF NOT FOUND OR correction.club_id IS DISTINCT FROM inv.club_id OR correction.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
   OR correction.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown IS DISTINCT FROM jsonb_build_object('category','correction','correction',public.fn_accounting_correction_payload(correction))
   OR inv.status IS DISTINCT FROM 'generated' OR inv.chips_transferred IS DISTINCT FROM false OR inv.transferred_at IS NOT NULL OR inv.due_at IS NOT NULL
  THEN RAISE EXCEPTION 'correction_document_delivery_source_unverified' USING ERRCODE='23514';END IF;
  users:=correction.audience_user_ids;sender:=correction.issuer_representative_id;
  issuer_kind:=correction.issuer_type;issuer_id:=correction.issuer_id;scope_id:=correction.club_id;
  issuer_name:=correction.issuer_name;recipient_name:=correction.payee_name;correction_payload:=public.fn_accounting_correction_payload(correction);
 ELSIF inv.invoice_type='cashier_cashout' THEN
  SELECT * INTO cashier FROM public.accounting_cashier_events WHERE invoice_id=inv.id;
  IF NOT FOUND OR cashier.club_id IS DISTINCT FROM inv.club_id OR cashier.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
    OR cashier.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown->'cashier' IS DISTINCT FROM public.fn_cashier_event_payload(cashier)
  THEN RAISE EXCEPTION 'cashier_delivery_event_missing' USING ERRCODE='23514';END IF;
  users:=cashier.audience_user_ids;sender:=cashier.issuer_representative_id;
  issuer_kind:='club';issuer_id:=cashier.club_id;scope_id:=cashier.club_id;
  issuer_name:=cashier.issuer_name;recipient_name:=cashier.player_name;
  cashier_payload:=public.fn_cashier_event_payload(cashier);
 ELSE
 SELECT array_agg(user_id ORDER BY user_id) INTO issuer_users FROM public.fn_accounting_party_users(inv.from_entity_type,issuer_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO recipient_users FROM public.fn_accounting_party_users(inv.to_entity_type,recipient_id);
 IF COALESCE(cardinality(issuer_users),0)=0 OR COALESCE(cardinality(recipient_users),0)=0
 THEN RAISE EXCEPTION 'accounting_invoice_recipient_missing' USING ERRCODE='23514'; END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO users FROM unnest(issuer_users||recipient_users) x;
 -- Club senders receive one weekly summary; individual payees still get their receipt immediately.
 IF inv.from_entity_type='club' AND inv.to_entity_type IN('agent','player')
    AND inv.source_ledger_id IS NOT NULL AND inv.breakdown->>'category' IN('rakeback','commission') THEN
   users:=recipient_users;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN
   issuer_kind:='union';issuer_id:=(inv.breakdown->>'union_id')::uuid;
 END IF;
 sender:=CASE WHEN issuer_kind='club' THEN (SELECT owner_id FROM public.clubs WHERE id=issuer_id)
              WHEN issuer_kind='union' THEN (SELECT owner_id FROM public.unions WHERE id=issuer_id)
              ELSE issuer_id END;
 IF sender IS NULL OR NOT sender=ANY(issuer_users||recipient_users) THEN RAISE EXCEPTION 'accounting_invoice_sender_missing' USING ERRCODE='23514'; END IF;
 issuer_name:=CASE WHEN issuer_kind='club' THEN (SELECT name FROM public.clubs WHERE id=issuer_id)
                   WHEN issuer_kind='union' THEN (SELECT name FROM public.unions WHERE id=issuer_id)
                   ELSE (SELECT username FROM public.profiles WHERE id=issuer_id) END;
 recipient_name:=CASE WHEN inv.to_entity_type='club' THEN (SELECT name FROM public.clubs WHERE id=recipient_id)
                      WHEN inv.to_entity_type='union' THEN (SELECT name FROM public.unions WHERE id=recipient_id)
                      ELSE (SELECT username FROM public.profiles WHERE id=recipient_id) END;
 END IF;
 IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN recipient_name:=(SELECT name FROM public.clubs WHERE id=inv.club_id); END IF;
 body:=CASE WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number||E'\nIssued By: '||COALESCE(issuer_name,inv.from_entity_type)||E'\nFor: '||COALESCE(recipient_name,inv.to_entity_type)
  ||E'\nDirection: '||initcap(inv.from_entity_type)||' To '||initcap(inv.to_entity_type)
  ||E'\nAmount: '||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips'
  ||E'\nStatus: '||initcap(inv.status)
  ||CASE WHEN inv.chips_transferred THEN E'\nTransfer Recorded: '||COALESCE(inv.transferred_at,inv.created_at)::text ELSE '' END
  ||CASE WHEN inv.due_at IS NOT NULL THEN E'\nDue: '||to_char(inv.due_at AT TIME ZONE 'America/Chicago','YYYY-MM-DD HH24:MI')||' Chicago Time' ELSE '' END
  ||CASE WHEN inv.breakdown ? 'period_start' THEN E'\nPeriod: '||(inv.breakdown->>'period_start')||' To '||COALESCE(inv.breakdown->>'period_end','') ELSE '' END
  ||CASE WHEN inv.notes IS NOT NULL THEN E'\n'||inv.notes ELSE '' END;
 FOR line IN SELECT key,value FROM jsonb_each_text(COALESCE(inv.breakdown,'{}'))
   WHERE key IN('rake_generated','rakeback_due','union_fee_kept','players_won','settled_in_chips','eco_amount','presettled','rake_earned','union_rake_earned','private_rake_earned','private_rake_banked','total_rake_funding','rake_received','paid_super_agents','paid_agents','paid_sub_agents','paid_players','total_paid_by_club','retained_by_club','downstream_redistributed','downstream_paid_super_agents','downstream_paid_agents','downstream_paid_sub_agents','downstream_paid_players') ORDER BY key
 LOOP
   IF line.value IS NOT NULL THEN body:=body||E'\n'||initcap(replace(line.key,'_',' '))||': '||to_char(line.value::numeric,'FM999,999,999,999,990.00'); END IF;
 END LOOP;
 IF inv.invoice_type='credit_limit_change' THEN body:=public.fn_accounting_credit_change_body_v1(credit_change.id,inv.invoice_number);
 ELSIF inv.invoice_type='cashier_cashout' THEN body:=public.fn_cashier_document_body(cashier.id,inv.invoice_number);
 ELSIF inv.invoice_type='accounting_correction' THEN body:=public.fn_accounting_correction_document_body(correction.id,inv.invoice_number);END IF;
 meta:=jsonb_build_object('kind','accounting_invoice' ,'invoice_id',inv.id,'invoice_number',inv.invoice_number,
   'club_id',inv.club_id,'source_ledger_id',inv.source_ledger_id,'source_credit_invoice_id',inv.source_credit_invoice_id,
   'source_credit_payment_id',inv.source_credit_payment_id,'amount',inv.net_amount,'currency','CHIPS','conversationId',NULL,'status',inv.status,
   'invoice_type',inv.invoice_type,'from_entity_type',inv.from_entity_type,'from_entity_id',inv.from_entity_id,
   'to_entity_type',inv.to_entity_type,'to_entity_id',inv.to_entity_id,'lines',inv.breakdown-'source_ledger_ids');
 IF inv.invoice_type='credit_limit_change' THEN meta:=meta||jsonb_build_object('credit_change',credit_payload);
 ELSIF inv.invoice_type='cashier_cashout' THEN meta:=meta||jsonb_build_object('cashier',cashier_payload);
 ELSIF inv.invoice_type='accounting_correction' THEN meta:=meta||jsonb_build_object('correction',correction_payload);END IF;
 SELECT id INTO page_id FROM public.social_pages WHERE linked_entity_id=scope_id::text AND linked_entity_type='club' ORDER BY id LIMIT 1;
 FOREACH person IN ARRAY users LOOP
   IF EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d WHERE d.invoice_id=inv.id AND d.recipient_id=person) THEN CONTINUE; END IF;
   -- One private accounting conversation per issuer, sender, scope and recipient.
   PERFORM pg_advisory_xact_lock(hashtextextended('accounting_conversation:'||scope_id::text||':'||issuer_id::text||':'||sender::text||':'||person::text,0));
   SELECT conversation_id INTO conv FROM public.accounting_conversations c
    WHERE c.scope_id=scope_id AND c.issuer_type=issuer_kind AND c.issuer_id=issuer_id AND c.sender_id=sender AND c.recipient_id=person;
   IF conv IS NULL THEN
     INSERT INTO public.social_conversations(is_group,group_name,context_entity_id,context_entity_type)
      VALUES(true,COALESCE(issuer_name,'Account')||' Accounting',page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END) RETURNING id INTO conv;
     INSERT INTO public.social_conversation_participants(conversation_id,user_id,context_entity_id,context_entity_type)
      SELECT conv,x,page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END FROM (SELECT DISTINCT unnest(ARRAY[sender,person]) AS x) members;
     INSERT INTO public.accounting_conversations(scope_id,issuer_type,issuer_id,sender_id,recipient_id,conversation_id)
      VALUES(scope_id,issuer_kind,issuer_id,sender,person,conv);
   END IF;
   -- Refuse a conversation whose audience changed instead of leaking invoices.
   IF EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id<>ALL(ARRAY[sender,person]))
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=person)
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=sender)
   THEN RAISE EXCEPTION 'accounting_conversation_audience_changed' USING ERRCODE='23514'; END IF;
   IF inv.invoice_type IN('cashier_cashout','accounting_correction','credit_limit_change') THEN meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);END IF;
   INSERT INTO public.social_messages(conversation_id,sender_id,content,message_type,media_metadata)
    VALUES(conv,sender,body,'invoice',meta) RETURNING id INTO msg;
   UPDATE public.social_conversations SET last_message_at=now(),last_message_preview=left(body,100),updated_at=now() WHERE id=conv;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.notifications(user_id,type,title,message,data,read,action_url,metadata)
    VALUES(person,'accounting_invoice',CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit Line Updated · ' WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded · ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held · ' WHEN 'approval' THEN 'Cashout Approved · ' ELSE 'Chips Returned · ' END WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number,
     CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit capacity reduced: '||to_char(inv.net_amount,'FM999,999,999,999,990.00')||'. No payment due.'
      ELSE CASE WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded: ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held: ' WHEN 'approval' THEN 'Cashout Approved: ' ELSE 'Chips Returned: ' END WHEN inv.chips_transferred AND inv.breakdown->>'category'='rakeback' THEN 'Rakeback Transfer Recorded: ' WHEN inv.chips_transferred AND inv.breakdown->>'category'='commission' THEN 'Commission Transfer Recorded: ' WHEN inv.chips_transferred THEN 'Transfer Recorded: ' ELSE 'Invoice Issued: ' END||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips' END,
     meta,false,'/hub/messenger?conversation='||conv::text,meta) RETURNING id INTO note;
   INSERT INTO public.accounting_invoice_deliveries(invoice_id,recipient_id,message_id,notification_id) VALUES(inv.id,person,msg,note);
   count_sent:=count_sent+1;
 END LOOP;
 SELECT count(*) INTO n FROM public.accounting_invoice_deliveries WHERE invoice_id=inv.id;
 UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id;
 RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',n,'new_deliveries',count_sent);
END $$;

CREATE OR REPLACE FUNCTION public.fn_invoice_accounting_ledger_transfer(p_ledger_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE leg public.chip_ledger%ROWTYPE; inv_id uuid; issuer_kind text; issuer_id uuid; payee_kind text; payee_id uuid; kind text; recorded_role text; routed boolean; correction public.accounting_correction_documents%ROWTYPE;
BEGIN
 SELECT * INTO leg FROM public.chip_ledger WHERE id=p_ledger_id;
 IF NOT FOUND OR leg.status IS DISTINCT FROM 'posted' OR leg.amount IS NULL OR leg.amount<=0
    OR leg.amount::text IN('NaN','Infinity','-Infinity') OR leg.amount<>round(leg.amount,2)
 THEN RAISE EXCEPTION 'invalid_accounting_transfer' USING ERRCODE='23514'; END IF;
 IF leg.category='correction' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_ledger_invoice:'||leg.id::text,0));
  SELECT * INTO correction FROM public.accounting_correction_documents WHERE source_ledger_id=leg.id;
  IF NOT FOUND THEN RAISE EXCEPTION 'historical_correction_document_unverified' USING ERRCODE='23514';END IF;
  SELECT id INTO inv_id FROM public.settlement_invoices WHERE source_ledger_id=leg.id;
  IF inv_id IS NOT NULL THEN
   IF inv_id IS DISTINCT FROM correction.invoice_id THEN RAISE EXCEPTION 'correction_document_invoice_collision' USING ERRCODE='23514';END IF;
   PERFORM public.fn_accounting_correction_assert_delivery(correction.id);
   RETURN inv_id;
  END IF;
  INSERT INTO public.settlement_invoices(id,club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
    gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,due_at,notes,source_ledger_id,created_at)
  VALUES(correction.invoice_id,correction.club_id,'accounting_correction',correction.issuer_type,correction.issuer_id::text,
    correction.payee_type,correction.payee_id::text,correction.amount,correction.amount,0,
    jsonb_build_object('category','correction','correction',public.fn_accounting_correction_payload(correction)),
    'generated',false,NULL,NULL,NULL,leg.id,correction.issued_at) RETURNING id INTO inv_id;
  IF NOT FOUND OR inv_id IS DISTINCT FROM correction.invoice_id THEN RAISE EXCEPTION 'correction_document_invoice_write_missing' USING ERRCODE='23514';END IF;
  PERFORM public.fn_deliver_accounting_invoice(inv_id);
  PERFORM public.fn_accounting_correction_assert_delivery(correction.id);
  RETURN inv_id;
 END IF;
 routed:=COALESCE(leg.metadata->>'routing_version'='3'
  AND current_setting('app.accounting_routing_context',true)=
   CASE WHEN leg.union_id IS NOT NULL THEN leg.union_id::text
    WHEN leg.metadata->>'accounting_scope_kind'='club' AND leg.metadata->>'accounting_scope_id'=leg.club_id::text
     THEN 'club:'||leg.club_id::text END
   ||':'||((leg.metadata->>'period_start')::timestamptz)::text||':'||((leg.metadata->>'period_end')::timestamptz)::text,false);
 recorded_role:=CASE WHEN routed THEN leg.metadata->>'payee_role_at_transfer' END;
 IF routed AND leg.to_type IN('player_wallet','agent_wallet') AND (recorded_role IS NULL OR recorded_role NOT IN('player','sub_agent','agent','super_agent')) THEN
  RAISE EXCEPTION 'routed_payment_recipient_role_missing' USING ERRCODE='23514'; END IF;

 IF leg.from_type IN('union_wallet','union_bank') THEN issuer_kind:='union';issuer_id:=leg.from_entity_id;
 ELSIF leg.from_type='club_treasury' THEN issuer_kind:='club';issuer_id:=leg.from_entity_id;
 ELSIF leg.from_type IN('player_wallet','agent_wallet') THEN issuer_id:=leg.from_entity_id;
   issuer_kind:=CASE WHEN routed OR leg.from_type='agent_wallet' OR EXISTS(SELECT 1 FROM public.agents a WHERE a.user_id=issuer_id AND a.club_id=leg.club_id) THEN 'agent' ELSE 'player' END;
 ELSIF leg.from_type='settlement_suspense' AND leg.category='rakeback' AND leg.club_id IS NOT NULL THEN
   -- Club-issued receipt for the existing clearing-account leg; preserve its actual source in breakdown.
   issuer_kind:='club';issuer_id:=leg.club_id;
 ELSE RAISE EXCEPTION 'unsupported_accounting_transfer_source' USING ERRCODE='23514'; END IF;
 -- Game payout journals retain the physical union_wallets.id store identity.
 -- Accounting parties use unions.id. Resolve only a matching, declared host;
 -- never rewrite the original journal or infer a different union.
 IF leg.category IN('wheel_prize','plinko_prize','crash_prize','crossing_prize','mines_prize')
    AND issuer_kind='union' AND leg.union_id IS NOT NULL
    AND EXISTS(SELECT 1 FROM public.union_wallets w WHERE w.id=issuer_id AND w.union_id=leg.union_id)
 THEN issuer_id:=leg.union_id; END IF;
 IF leg.to_type IN('union_wallet','union_bank') THEN payee_kind:='union';payee_id:=leg.to_entity_id;
 ELSIF leg.to_type='club_treasury' THEN payee_kind:='club';payee_id:=leg.to_entity_id;
 ELSIF leg.to_type IN('player_wallet','agent_wallet') THEN
   payee_id:=leg.to_entity_id;
   payee_kind:=CASE WHEN routed THEN CASE WHEN recorded_role='player' THEN 'player' ELSE 'agent' END WHEN leg.category='commission' OR EXISTS(SELECT 1 FROM public.agents a WHERE a.user_id=payee_id AND a.club_id=leg.club_id) THEN 'agent' ELSE 'player' END;
 ELSE RAISE EXCEPTION 'unsupported_accounting_transfer_recipient' USING ERRCODE='23514'; END IF;
 kind:=CASE WHEN issuer_kind='union' AND payee_kind='club' THEN 'union_to_club'
            WHEN issuer_kind='club' AND payee_kind='agent' THEN 'club_to_agent'
            WHEN issuer_kind='agent' AND payee_kind='agent' THEN 'agent_to_subagent'
            WHEN issuer_kind='agent' AND payee_kind='player' THEN 'agent_to_player' ELSE 'transaction_receipt' END;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_ledger_invoice:'||leg.id::text,0));
 SELECT id INTO inv_id FROM public.settlement_invoices WHERE source_ledger_id=leg.id;
 IF inv_id IS NULL THEN
   INSERT INTO public.settlement_invoices(club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
    gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,notes,source_ledger_id)
   VALUES(COALESCE(leg.club_id,leg.union_id),kind,issuer_kind,issuer_id::text,payee_kind,payee_id::text,leg.amount,leg.amount,0,
    COALESCE(leg.metadata,'{}'::jsonb)||jsonb_build_object('ledger_id',leg.id,'category',leg.category,'ledger_from_type',leg.from_type,
      'ledger_from_entity_id',leg.from_entity_id,'ledger_to_type',leg.to_type,'ledger_to_entity_id',leg.to_entity_id,
      'payee_role_at_transfer',CASE WHEN routed AND recorded_role IS NOT NULL THEN recorded_role WHEN payee_kind='player' THEN 'player' ELSE (SELECT a.role FROM public.agents a WHERE a.user_id=payee_id AND a.club_id=leg.club_id ORDER BY a.id LIMIT 1) END),
    'paid',true,leg.created_at,'Receipt For A Posted Accounting Transfer. This Does Not Certify The Entire Weekly Close.',leg.id)
   RETURNING id INTO inv_id;
 END IF;
 PERFORM public.fn_deliver_accounting_invoice(inv_id);
 RETURN inv_id;
END $$;

CREATE OR REPLACE FUNCTION public.fn_raise_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_title IS NULL OR btrim(p_title) = '' THEN RETURN; END IF;
  INSERT INTO public.notifications (user_id, type, title, message, link, data)
  VALUES (p_user_id, p_type, p_title, p_message, p_link, COALESCE(p_data, '{}'::jsonb));
END; $$;

CREATE OR REPLACE FUNCTION public.fn_raise_server_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb DEFAULT '{}'::jsonb, p_dedupe_key text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id     uuid;
  v_sev    text;
  v_source text;
  v_key    text;
  v_entity text;
  v_recent integer;
BEGIN
  v_sev := lower(coalesce(p_severity, 'info'));
  IF v_sev NOT IN ('critical', 'warning', 'info') THEN
    v_sev := 'info';
  END IF;

  v_source := left(coalesce(nullif(p_source, ''), 'unknown'), 200);
  v_entity := left(nullif(btrim(coalesce(p_entity_id, '')), ''), 200);
  v_key    := left(nullif(btrim(coalesce(p_dedupe_key, '')), ''), 200);
  IF v_key IS NULL THEN
    v_key := v_entity;
  END IF;

  /* ONE OPEN ALERT PER THING THAT IS WRONG. Not per pass over it. */
  IF v_key IS NOT NULL THEN
    SELECT fa.id INTO v_id
      FROM public.financial_alerts fa
     WHERE fa.source = v_source
       AND fa.resolved IS NOT TRUE
       AND fa.context ->> 'dedupe_key' = v_key
     ORDER BY fa.created_at DESC
     LIMIT 1;
    IF v_id IS NOT NULL THEN
      RETURN v_id;
    END IF;
  END IF;

  SELECT count(*) INTO v_recent
    FROM public.financial_alerts
   WHERE created_at > now() - interval '1 minute'
     AND source = v_source
     AND context ->> 'channel' = 'server_rpc';

  IF v_recent >= 60 THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.financial_alerts (severity, source, message, context, resolved)
  VALUES (
    v_sev,
    v_source,
    left(coalesce(nullif(p_message, ''), '(no message)'), 4000),
    coalesce(p_context, '{}'::jsonb)
      || jsonb_build_object('channel', 'server_rpc')
      || CASE WHEN v_key IS NULL THEN '{}'::jsonb
              ELSE jsonb_build_object('dedupe_key', v_key) END
      || CASE WHEN v_entity IS NULL THEN '{}'::jsonb
              ELSE jsonb_build_object('entity_id', v_entity) END,
    false
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.fn_union_club_rake_basis(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_live boolean DEFAULT false) RETURNS TABLE(club_id uuid, game_type text, rake_in numeric, rate numeric, payout numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sref text;
BEGIN
  IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR p_end <= p_start THEN
    RETURN;
  END IF;

  /* THE WITNESS FIRST. A period that has been closed stored the rows it was
     paid from; a statement for that period describes THAT, never a
     recomputation over attribution tables that may since have moved. */
  v_sref := p_union_id::text || ':'
    || to_char(p_start at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(p_end   at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  IF EXISTS (SELECT 1 FROM public.ca_settlements s
              WHERE s.settlement_type = 'union_rakeback_close' AND s.union_id = p_union_id
                AND s.state = 'final' AND s.external_ref = v_sref
                AND s.totals ? 'basis_detail') THEN
    RETURN QUERY
      SELECT (d->>'club_id')::uuid, d->>'game_type',
             (d->>'rake_in')::numeric, (d->>'rate')::numeric, (d->>'payout')::numeric
        FROM public.ca_settlements s
        CROSS JOIN LATERAL jsonb_array_elements(s.totals->'basis_detail') d
       WHERE s.settlement_type = 'union_rakeback_close' AND s.union_id = p_union_id
         AND s.state = 'final' AND s.external_ref = v_sref;
    RETURN;
  END IF;

  -- Open/current statements and the close read exactly the same certified
  -- source plan. An old hourly projection cannot replace earning contracts.
  RETURN QUERY SELECT (d->>'club_id')::uuid,d->>'game_type',(d->>'rake_in')::numeric,
    (d->>'rate')::numeric,(d->>'payout')::numeric
   FROM jsonb_array_elements(public.fn_accounting_union_earned_plan(p_union_id,p_start,p_end)->'basis_detail')d;
END;
$$;
